var roots=new UnityEngine.GameObject[2];var failures=new System.Collections.Generic.List<string>();float maxBoundsError=0;int checks=0;try{for(int i=0;i<2;i++){roots[i]=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Resources/Ships/ShipV3Test.prefab");roots[i].GetComponent<UnityEngine.Rigidbody>().interpolation=UnityEngine.RigidbodyInterpolation.None;}var bodies=roots.Select(r=>r.GetComponent<UnityEngine.Rigidbody>()).ToArray();var scratch=new[]{new System.Collections.Generic.List<UnityEngine.Rigidbody>(64),new System.Collections.Generic.List<UnityEngine.Rigidbody>(64)};var colliders=roots.Select(r=>r.GetComponentsInChildren<UnityEngine.Collider>(false).Where(c=>c.enabled).ToArray()).ToArray();UnityEngine.Physics.SyncTransforms();for(int step=0;step<12;step++){var p=new UnityEngine.Vector3(-635+step*.3f,-step*9,-788+step*.2f);var q=UnityEngine.Quaternion.Euler(step*2.5f,180+step*6,-step*1.3f);for(int i=0;i<2;i++){PirateSlop.Ships.ShipBodyPose.Enabled=i==1;PirateSlop.Ships.ShipBodyPose.Apply(bodies[i],p,q,scratch[i],true);}UnityEngine.Physics.SyncTransforms();for(int c=0;c<colliders[0].Length;c++){var a=colliders[0][c].bounds;var b=colliders[1][c].bounds;float error=UnityEngine.Vector3.Distance(a.center,b.center);maxBoundsError=UnityEngine.Mathf.Max(maxBoundsError,error);if(error>.003f||UnityEngine.Vector3.Distance(a.size,b.size)>.003f)failures.Add(step+":"+colliders[0][c].name+":"+error);checks++;}}return new{checks,colliders=colliders[0].Length,maxBoundsError,failures=failures.Take(10).ToArray(),totalFailures=failures.Count};}finally{PirateSlop.Ships.ShipBodyPose.Enabled=true;foreach(var r in roots)if(r!=null)UnityEditor.PrefabUtility.UnloadPrefabContents(r);}
